export function createFreshChannel(
  baseName: string,
  opts?: RealtimeChannelOptions,
  exactTopic = false
): RealtimeChannel {
  const channelName = exactTopic
    ? baseName
    : `${baseName}-${Math.random().toString(36).substring(2, 9)}`;

  try {
    const existing = supabase.getChannels().find(
      (ch) =>
        ch.topic === `realtime:${baseName}` ||
        ch.topic === baseName ||
        ch.topic === `realtime:${channelName}` ||
        ch.topic === channelName
    );
    if (existing) {
      supabase.removeChannel(existing);
    }
  } catch {
    // Ignore cleanup errors
  }

  return supabase.channel(channelName, opts);
}

